package dev.interview.orders.outbox;
import io.micrometer.core.instrument.MeterRegistry; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class OutboxPublisher {private final OutboxRepository repo;private final KafkaTemplate<String,String> kafka;private final MeterRegistry metrics;public OutboxPublisher(OutboxRepository r,KafkaTemplate<String,String> k,MeterRegistry m){repo=r;kafka=k;metrics=m;}
 @Scheduled(fixedDelayString="${app.outbox.poll-ms:1000}") @Transactional public void publish(){for(var event:repo.findTop100ByPublishedAtIsNullOrderByCreatedAtAsc()){kafka.send("orders.v1",event.getAggregateId().toString(),event.getPayload()).join();event.markPublished();metrics.counter("orders_outbox_published_total","type",event.getEventType()).increment();}metrics.gauge("orders_outbox_backlog",repo,OutboxRepository::countByPublishedAtIsNull);}}
